#include <Wire.h>
#include <Adafruit_VL53L0X.h>

Adafruit_VL53L0X tof;
VL53L0X_RangingMeasurementData_t measurement;

const uint8_t BUZZER_PIN = 4;
const uint8_t SDA_PIN = 8;
const uint8_t SCL_PIN = 9;
const uint16_t MAX_DISTANCE_MM = 1200;
const uint16_t MIN_DISTANCE_MM = 50;
const uint16_t BEEP_MS = 55;
const uint16_t FAR_INTERVAL_MS = 700;
const uint16_t NEAR_INTERVAL_MS = 100;

unsigned long lastBeep = 0;
bool isBeeping = false;
unsigned long beepStarted = 0;
unsigned long lastSerialPrint = 0;
const uint16_t SERIAL_INTERVAL_MS = 250;

void setup() {
  Serial.begin(115200);
  pinMode(BUZZER_PIN, OUTPUT);
  noTone(BUZZER_PIN);
  Wire.begin(SDA_PIN, SCL_PIN);

  if (!tof.begin(0x29, false, &Wire)) {
    // Stay silent if the sensor is not detected.
    while (true) {
      noTone(BUZZER_PIN);
      delay(100);
    }
  }
}

void loop() {
  unsigned long now = millis();
  if (isBeeping && now - beepStarted >= BEEP_MS) {
    noTone(BUZZER_PIN);
    isBeeping = false;
  }

  tof.rangingTest(&measurement, false);
  if (now - lastSerialPrint >= SERIAL_INTERVAL_MS) {
    if (measurement.RangeStatus == 4) {
      Serial.println("Distance: out of range");
    } else {
      Serial.print("Distance: ");
      Serial.print(measurement.RangeMilliMeter);
      Serial.println(" mm");
    }
    lastSerialPrint = now;
  }

  if (measurement.RangeStatus == 4 || measurement.RangeMilliMeter > MAX_DISTANCE_MM) {
    noTone(BUZZER_PIN);
    isBeeping = false;
    return;
  }

  uint16_t distance = constrain(measurement.RangeMilliMeter, MIN_DISTANCE_MM, MAX_DISTANCE_MM);
  uint16_t interval = map(distance, MIN_DISTANCE_MM, MAX_DISTANCE_MM,
                          NEAR_INTERVAL_MS, FAR_INTERVAL_MS);
  if (!isBeeping && now - lastBeep >= interval) {
    tone(BUZZER_PIN, 2200);
    beepStarted = now;
    lastBeep = now;
    isBeeping = true;
  }
}
